(34301, 0, 'ruRU', 'Кто такие Древние?', NULL),
(34578, 0, 'ruRU', 'Давай, Рокко.', NULL),
(36561, 0, 'ruRU', 'Заткнись, волосатая отрыжка! Скоро ты научишься подчиняться своим гномьим повелителям!!', NULL),
(36561, 1, 'ruRU', 'Тебе лучше привыкнуть к этому, вяленое мясо. Альянс в основном считает вас питомцами. Умеете делать трюки?', NULL),
(36571, 0, 'ruRU', 'У тебя не будет выбора, когда твой народ поработят карательные отряды кованых сапог Альянса!', NULL),
(36571, 1, 'ruRU', 'Ты всё болтаешь, а я слышу только «бла-бла, мой народ купается в собственной грязи».', NULL),
(36571, 2, 'ruRU', '<Вырвать пирсинг у него из живота.>', NULL),
(36599, 0, 'ruRU', '«Эм... Ал''тет... ла ц''толгар? Или как-то так».', NULL),
(36618, 0, 'ruRU', 'Не так быстро, медвежья морда. Сначала мне нужен массаж ног.', NULL),
(36618, 1, 'ruRU', 'Что это за запах? Это от тебя? Серьёзно.', NULL),
(36618, 2, 'ruRU', 'Альянс требует поставку свежих младенцев каждое новолуние для наших трудовых лагерей для младенцев.', NULL),
(36799, 0, 'ruRU', 'Отправиться в Ваш''ир', NULL),
(36859, 0, 'ruRU', 'Нет-нет-нет, ты не понимаешь. Я здесь, чтобы помочь.', NULL),
(36861, 0, 'ruRU', 'Встретил кого-то? Я не знал, что здесь есть другие драконы.', NULL),
(36863, 0, 'ruRU', '...целитель духов?', NULL),
(36865, 0, 'ruRU', 'Прости, я не хотел быть грубым, просто...', NULL),
(36867, 0, 'ruRU', 'Я вообще не это хотел сказать.', NULL),
(36869, 0, 'ruRU', 'Я... забудь. Я здесь, чтобы предупредить тебя: чёрные драконы охотятся за тобой.', NULL),
(36871, 0, 'ruRU', 'Ты уже знаешь? Почему же ты не пойдёшь остановить их?', NULL),
(36873, 0, 'ruRU', 'Но Калесгос уже пытается остановить их. Ему нужна твоя помощь.', NULL),
(36875, 0, 'ruRU', 'Значит, ты пойдёшь?', NULL),
(36877, 0, 'ruRU', 'Я сразу же сообщу ему. Встретимся на Соболином Хребте.', NULL),
(38237, 0, 'ruRU', 'Хорошо, я готов.', NULL),
(38409, 0, 'ruRU', 'Готовы на все сто!', NULL),
